/**
 * The production half of the shared writing-dynamics contract (#468).
 *
 * `writing_dynamics.py` was the only implementation, on a FastAPI path that is
 * not deployed (ADR 0001). Production collected the telemetry and analysed
 * none of it while blesc.jp described noticing changes in how a student writes
 * against their own past. Option B ports the analysis here; the fixture in
 * `sentra/shared/writing_dynamics_conformance.json` is generated by running the
 * Python, and this suite fails the build the moment the port disagrees with it.
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it } from "node:test";

import { RAMP_UP_DAYS } from "../src/lib/baseline.ts";
import { EntryTelemetryCollector } from "../src/lib/telemetry.ts";
import {
  CHANGE_Z_THRESHOLD,
  MIN_FIELD_INPUTS,
  MIN_STD,
  PIPELINE_VERSION,
  WRITING_CHANGE_FEATURES,
  WRITING_CHANGE_FIELD,
  WRITING_CHANGE_VERSION,
  educatorEvidence,
  historyDaysFromRows,
  pyRound,
  writingChangeAgainstBaseline,
  writingDynamicsForSession,
} from "../src/lib/writingDynamics.ts";

const HERE = dirname(fileURLToPath(import.meta.url));
const CONTRACT = JSON.parse(
  readFileSync(resolve(HERE, "../../shared/writing_dynamics_conformance.json"), "utf8"),
);

const TOLERANCE = 1e-9;

/** Numbers within TOLERANCE, everything else exactly; key sets must match. */
function assertConforms(actual, expected, path) {
  if (expected === null || typeof expected !== "object") {
    if (typeof expected === "number") {
      assert.equal(typeof actual, "number", `${path}: expected a number, got ${JSON.stringify(actual)}`);
      assert.ok(Math.abs(actual - expected) <= TOLERANCE, `${path}: expected ${expected}, got ${actual}`);
    } else {
      assert.equal(actual, expected, path);
    }
    return;
  }
  if (Array.isArray(expected)) {
    assert.ok(Array.isArray(actual), `${path}: expected an array`);
    assert.equal(actual.length, expected.length, `${path}: length`);
    expected.forEach((item, index) => assertConforms(actual[index], item, `${path}[${index}]`));
    return;
  }
  assert.ok(actual && typeof actual === "object", `${path}: expected an object`);
  assert.deepEqual(Object.keys(actual).sort(), Object.keys(expected).sort(), `${path}: keys`);
  for (const key of Object.keys(expected)) assertConforms(actual[key], expected[key], `${path}.${key}`);
}

describe("writing dynamics — shared contract", () => {
  it("pins the same constants as the backend", () => {
    assert.equal(CONTRACT.contract, "writing_dynamics");
    assert.equal(CONTRACT.pipeline_version, PIPELINE_VERSION);
    assert.equal(CONTRACT.change_pipeline_version, WRITING_CHANGE_VERSION);
    assert.equal(CONTRACT.change_field, WRITING_CHANGE_FIELD);
    assert.deepEqual(CONTRACT.change_features, [...WRITING_CHANGE_FEATURES]);
    assert.equal(CONTRACT.ramp_up_days, RAMP_UP_DAYS);
    assert.equal(CONTRACT.min_field_inputs, MIN_FIELD_INPUTS);
    assert.equal(CONTRACT.change_z_threshold, CHANGE_Z_THRESHOLD);
    assert.equal(CONTRACT.min_std, MIN_STD);
    assert.ok(CONTRACT.dynamics_cases.length >= 5);
    assert.ok(CONTRACT.change_cases.length >= 10);
  });

  for (const testCase of CONTRACT.dynamics_cases) {
    it(`dynamics: ${testCase.name}`, () => {
      const actual = writingDynamicsForSession(testCase.input.field_metrics, testCase.input.events);
      assertConforms(actual, testCase.expected, testCase.name);
    });
  }

  for (const testCase of CONTRACT.change_cases) {
    it(`change: ${testCase.name}`, () => {
      const actual = writingChangeAgainstBaseline(testCase.current, testCase.history_days);
      assertConforms(actual, testCase.expected, testCase.name);
    });
  }
});

describe("Python rounding, reproduced", () => {
  it("rounds an exact binary half to even, as Python's round() does", () => {
    assert.equal(pyRound(0.0625, 3), 0.062);
    assert.equal(pyRound(0.1875, 3), 0.188);
    assert.equal(pyRound(1 / 128, 6), 0.007812);
    assert.equal(pyRound(-0.0625, 3), -0.062);
  });

  it("agrees with toFixed everywhere else", () => {
    for (const value of [1 / 3, 2 / 3, 0.1 + 0.2, 262.18487394957984, 66.66666666666667, 0.0005]) {
      assert.equal(pyRound(value, 3), Number(value.toFixed(3)));
      assert.equal(pyRound(value, 6), Number(value.toFixed(6)));
    }
  });
});

describe("writing dynamics on the collector's own payload", () => {
  it("analyses exactly what EntryTelemetryCollector sends", () => {
    let now = 1_000_000;
    const collector = new EntryTelemetryCollector({ sessionId: "sess-wd", now: () => now });
    const lengths = [3, 8, 14, 9, 20, 27, 31];
    const gaps = [400, 300, 4000, 200, 300, 9000, 250];
    for (let index = 0; index < lengths.length; index += 1) {
      now += gaps[index];
      collector.input("journal_entry", lengths[index]);
    }
    const payload = collector.finalize();
    const dynamics = writingDynamicsForSession(payload.field_metrics, payload.events).journal_entry;

    assert.equal(dynamics.input_count, 7);
    assert.equal(dynamics.final_length, 31);
    // The collector's own 2500 ms rule, read from field_metrics: two pauses.
    assert.equal(dynamics.pause_count, 2);
    assert.equal(dynamics.max_pause_ms, 9000);
    assert.equal(dynamics.deletion_ratio, pyRound(1 / 7, 6));
    // No text anywhere in the output, only lengths and times.
    assert.ok(Object.values(dynamics).every((value) => typeof value === "number" || typeof value === "string" || value === null));
  });
});

describe("what an educator may receive", () => {
  const observed = CONTRACT.change_cases.find((c) => c.name === "longer_hesitation_is_observed");

  it("is feature and direction, never a number", () => {
    const outcome = writingChangeAgainstBaseline(observed.current, observed.history_days);
    const evidence = educatorEvidence(outcome);
    assert.ok(evidence && evidence.length > 0);
    for (const item of evidence) {
      assert.deepEqual(Object.keys(item).sort(), ["direction", "feature"]);
      assert.ok(!Object.values(item).some((value) => typeof value === "number"));
    }
  });

  it("is nothing for every status except an observed change", () => {
    for (const name of [
      "cold_start_day_one",
      "thirteen_days_is_not_enough",
      "an_ordinary_day_is_within_baseline",
      "a_short_entry_today_is_not_compared",
      "a_feature_that_never_moved_is_degenerate_not_a_change",
    ]) {
      const testCase = CONTRACT.change_cases.find((c) => c.name === name);
      assert.equal(educatorEvidence(writingChangeAgainstBaseline(testCase.current, testCase.history_days)), null, name);
    }
  });

  it("comes with no comparison at all before the ramp completes", () => {
    for (let days = 0; days < RAMP_UP_DAYS; days += 1) {
      const outcome = writingChangeAgainstBaseline(observed.current, observed.history_days.slice(0, days));
      assert.equal(outcome.status, "not_enough_data");
      assert.ok(!("z_scores" in outcome));
    }
  });
});

describe("historyDaysFromRows", () => {
  it("buckets by day, most recent first, and excludes today and later", () => {
    const days = historyDaysFromRows(
      [
        { day: "2026-10-03", features: { input_count: 1 } },
        { day: "2026-10-01", features: { input_count: 2 } },
        { day: "2026-10-03", features: { input_count: 3 } },
        { day: "2026-10-05", features: { input_count: 4 } },
        { day: "2026-10-04", features: { input_count: 5 } },
      ],
      "2026-10-05",
    );
    assert.deepEqual(days, [
      [{ input_count: 5 }],
      [{ input_count: 1 }, { input_count: 3 }],
      [{ input_count: 2 }],
    ]);
  });
});
